from fastapi import FastAPI
app = FastAPI()
class DeferredQueue:
    def __init__(self): self.pending = []
    def enqueue(self, item): self.pending.append(item)
queue = DeferredQueue()
def process(item): return item
def run_pending():
    while queue.pending:
        process(queue.pending.pop(0))
@app.post('/upload', status_code=202)
def upload():
    queue.enqueue('parse')
    return {'queued': True}
@app.get('/health')
def health():
    return {'ok': True}
